// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(c) && recipient != address(this) && recipient != address(0));
        vm.deal(address(c), amount);
        uint256 recipientBalanceBefore = recipient.balance;
        vm.prank(address(this));
        try c.withdrawAll(recipient) { } catch { }
        assertTrue(recipient.balance - recipientBalanceBefore == amount);
    }
}
